// One entry per distinct domain; full addresses are cut down to the domain. The register entry of a supplier is
// kept in the workflow's static data, so the paid legal notice step runs only for domains that are new on the
// list or whose entry is older than refreshLegalNoticeDays.
const s = $('Settings').first().json;
const raw = String(s.supplierDomains ?? '');
const websites = [...new Set(raw.split(/[\s,;]+/)
  .map(d => d.trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[/?#]/)[0])
  .filter(d => d.includes('.')))];
if (websites.length === 0) {
  throw new Error('Settings: add at least one supplier domain to supplierDomains.');
}
const given = s.refreshLegalNoticeDays;
const refreshDays = given === '' || given === null || given === undefined ? NaN : Number(given);
if (!Number.isFinite(refreshDays) || refreshDays < 0) {
  throw new Error('Settings: refreshLegalNoticeDays must be a number, 0 or more (0 reads every legal notice on every run).');
}
const known = $getWorkflowStaticData('global').suppliers || {};
const today = new Date().toISOString().slice(0, 10);
const toResolve = websites.filter(domain => {
  const record = known[domain];
  const age = record && record.resolvedOn ? (Date.parse(today) - Date.parse(record.resolvedOn)) / 86400000 : NaN;
  return !(age < refreshDays);  // not known, without a date or old: read the legal notice
});
return [{ json: { websites, toResolve, remembered: websites.length - toResolve.length, today } }];

// A legal notice run that failed must not stop the daily check: suppliers that were read before keep their
// entry, the others are listed as not checked with Apify's own status message.
const run = $input.first().json;
const message = run.statusMessage || '';
const problem = run.status !== 'SUCCEEDED' || /^Rejected/i.test(message)
  ? `Imprint & VAT Check run ${run.id} ended with status ${run.status}: ${message}` : null;
if (!run.defaultDatasetId) {
  throw new Error(`Run ${run.id} has no dataset.`);
}
return [{ json: { runId: run.id, datasetId: run.defaultDatasetId, problem } }];

// Suppliers whose legal notice names a German register entry become monitor entries: court, type and number
// identify the company exactly. A German supplier whose legal notice gives no court or no register number is
// passed on by name and town instead; the monitor marks such rows with matchedBy "name". Each supplier's entry
// is kept in the workflow's static data; a supplier whose legal notice could not be read this time keeps the
// entry it had. Everything else goes to the report as not checked, with the reason.
const s = $('Settings').first().json;
const watchlistId = String(s.watchlistId ?? '').trim();
if (!watchlistId) {
  throw new Error('Settings: watchlistId is empty. Without it every run returns and charges every company.');
}
const SIGNALS = ['insolvency', 'register', 'vat', 'hiring'];
const alertOn = String(s.alertOn ?? '').split(',').map(x => x.trim()).filter(Boolean);
const unknown = alertOn.filter(x => !SIGNALS.includes(x));
if (unknown.length > 0) {
  throw new Error(`Settings: alertOn knows only ${SIGNALS.join(', ')} (got ${unknown.join(', ')}).`);
}
const plan = $('Split known and new suppliers').first().json;
let lookup = null;  // the legal notice run of this execution, when there was one
try { lookup = $('Check legal notice run').first().json; } catch (error) { lookup = null; }
const memory = $getWorkflowStaticData('global');
const known = { ...(memory.suppliers || {}) };
const TYPES = new Set(['HRB', 'HRA', 'GnR', 'VR']);
const fresh = new Set();
const failed = new Map();
for (const item of $input.all()) {
  const row = item.json;
  if (!row || !row.input || !row.status) continue;  // the IF node's false branch brings no legal notice rows
  const domains = [row.input, ...(row.duplicateInputs || [])].map(d => String(d).toLowerCase());
  if (row.status !== 'found') {
    // Not remembered: the next run reads this legal notice again.
    for (const d of domains) failed.set(d, `legal notice not read (status ${row.status}, ${row.reason})`);
    continue;
  }
  const german = !row.country || row.country === 'DE';
  const numbered = TYPES.has(row.registerType) && row.registerNumber && german;
  let record;
  if (numbered && row.registerCourt) {
    // The Impressum gives the number with its type ("HRB 12345"); the monitor takes court, type and number apart.
    const entry = { registerCourt: row.registerCourt, registerType: row.registerType,
      registerNumber: String(row.registerNumber).replace(/^(HRB|HRA|GnR|VR)\s*/i, '') };
    if (row.companyName) entry.name = row.companyName;
    if (row.vatId) entry.vatId = row.vatId;
    record = { resolvedOn: plan.today, entry };
  } else {
    // The monitor needs court, type and number together. Without them a company in Germany is given by name and
    // town (no website: the monitor would read the same legal notice and stop at the same gap).
    const abroad = row.country && row.country !== 'DE' ? ` (country ${row.country})` : '';
    const reason = numbered ? `the legal notice gives ${row.registerNumber} without its register court`
      : `the legal notice names no German register entry${abroad}`;
    if (row.country === 'DE' && row.companyName && row.city) {
      const entry = { name: row.companyName, city: row.city };
      if (row.vatId) entry.vatId = row.vatId;
      record = { resolvedOn: plan.today, entry, byName: reason };
    } else {
      record = { resolvedOn: plan.today, entry: null, reason };
    }
  }
  for (const d of domains) {
    known[d] = record;
    fresh.add(d);
  }
}
for (const d of plan.toResolve) {
  if (!fresh.has(d) && !failed.has(d)) {
    failed.set(d, lookup && lookup.problem ? lookup.problem
      : 'no row from the Imprint & VAT Check (see the record OUTPUT of its run)');
  }
}
const companies = [];
const notChecked = [];
const notRefreshed = [];
const byName = [];
const seenRegister = new Map();
const suppliers = {};  // what is remembered from here on: only domains that are still on the list
for (const domain of plan.websites) {
  const record = known[domain];
  if (!record) {
    notChecked.push({ domain, reason: failed.get(domain) || 'legal notice not read yet' });
    continue;
  }
  suppliers[domain] = record;
  if (failed.has(domain)) notRefreshed.push({ domain, reason: failed.get(domain), entryFrom: record.resolvedOn });
  if (!record.entry) {
    notChecked.push({ domain, reason: record.reason });
    continue;
  }
  const key = (record.byName ? `name|${record.entry.name}|${record.entry.city}`
    : `${record.entry.registerCourt}|${record.entry.registerType}|${record.entry.registerNumber}`).toLowerCase();
  if (seenRegister.has(key)) {
    notChecked.push({ domain, reason: `same ${record.byName ? 'company' : 'register entry'} as ${seenRegister.get(key)}` });
    continue;
  }
  seenRegister.set(key, domain);
  companies.push({ ...record.entry, ref: domain });
  if (record.byName) {
    byName.push({ domain, name: record.entry.name, city: record.entry.city,
      note: `given to the monitor by name and town: ${record.byName}` });
  }
}
memory.suppliers = suppliers;
if (companies.length === 0) {
  throw new Error('No supplier with a German register entry: ' + JSON.stringify(notChecked));
}
const monitorInput = { companies, watchlistId, maxCompanies: Math.min(10000, companies.length) };
if (alertOn.length > 0) monitorInput.alertOn = alertOn;
return [{ json: { monitorInput, notChecked, notRefreshed, byName, legalNoticesRead: fresh.size,
  entriesRemembered: Object.keys(suppliers).length } }];

// Stops here when the run did not succeed or the actor rejected its input, with Apify's own status message.
const run = $input.first().json;
const message = run.statusMessage || '';
if (run.status !== 'SUCCEEDED' || /^Rejected/i.test(message)) {
  throw new Error(`Run ${run.id} ended with status ${run.status}: ${message}`);
}
if (!run.defaultDatasetId) {
  throw new Error(`Run ${run.id} has no dataset.`);
}
return [{ json: { runId: run.id, datasetId: run.defaultDatasetId, statusMessage: message } }];

// One item per row of the monitor (with a watchlist: only companies where something changed) and one item per
// domain that could not be checked. No change and nothing left out: no item, so a notification stays quiet.
const built = $('Build monitor entries').first().json;
const byName = new Map((built.byName || []).map(x => [x.domain, x.note]));
const changes = $input.all().map(item => item.json).filter(row => row && row.status)
  .map(row => ({
    json: {
      rowType: 'change',
      supplier: row.ref ?? null,
      matchedBy: row.matchedBy ?? null,
      supplierNote: byName.get(row.ref) ?? null,
      candidates: row.candidates ?? [],
      companyName: row.companyName ?? null,
      register: [row.registerCourt, row.registerType, row.registerNumber].filter(Boolean).join(' '),
      change: row.change ?? null,
      changes: row.changes ?? [],
      riskLevel: row.riskLevel ?? null,
      riskReasons: row.riskReasons ?? [],
      insolvencyStatus: row.insolvency ? row.insolvency.status ?? null : null,
      deletionAnnounced: row.register ? row.register.deletionAnnounced ?? null : null,
      vatValid: row.vat ? row.vat.valid ?? null : null,
      openPositions: row.hiring ? row.hiring.openPositions ?? null : null,
      status: row.status,
      sourceErrors: row.sourceErrors ?? [],
      checkedAt: row.checkedAt ?? null,
    },
  }));
const skipped = (built.notChecked || [])
  .map(x => ({ json: { rowType: 'not_checked', supplier: x.domain, reason: x.reason } }));
return [...changes, ...skipped];
